'use strict';
(() => {
const SITE_BASE="/Coolex/";
// Keep logical catalogue IDs stable across root and subdirectory deployments.
function siteUrl(path){return path.startsWith('/')&&!path.startsWith('//')&&!path.startsWith(SITE_BASE)?SITE_BASE.slice(0,-1)+path:path}
function currentPath(){const physical=decodeURI(location.pathname);const logical=physical.startsWith(SITE_BASE)?physical.slice(SITE_BASE.length-1):physical===SITE_BASE.slice(0,-1)?'/':physical;return logical.replace(/\/index\.html$/,'/').replace(/\/$/,'')||'/'}
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',diagonal:'<path d="M6 18 18 6M6 6h12v12"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',play:'<path d="m9 5 11 7-11 7z" fill="currentColor" stroke="none"/>',phone:'<path d="m7 3 3 5-3 3c2 3 3 4 6 6l3-3 5 3-1 4C11 23 1 13 3 4z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',check:'<path d="m5 12 4 4L19 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>'};
const icon=n=>`<svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const button=(label,cls='btn-red',href='/catalog',ico='arrow')=>`<a class="btn ${cls}" href="${escape(siteUrl(href))}">${escape(label)}${icon(ico)}</a>`;
const I18n=window.CoolexI18n;
const t=(key,vars)=>I18n.t(key,vars);
const languageRoot=document.getElementById('language-root');
const mobileNavigation=window.matchMedia('(max-width:1180px)');
const pageTitle=p=>I18n.title(p);
const groupTitle=name=>I18n.group(name);
const phone='+91 9848887467',tel='tel:+919848887467';
const channels={telugu:'https://www.youtube.com/channel/UCb_fQfKVxkoxljwfqC_k1HQ',english:'https://www.youtube.com/@coolexfoodmachines9127'};
const maps={vijayawada:'https://maps.app.goo.gl/653Wmcsr9xBQD3ks9',hyderabad:'https://maps.app.goo.gl/yhjuN6iiyf7UsLZM9'};
let DATA,PAGES,EQUIPMENT,CONCEPTS,HOME,VIDEO_LIBRARY=[],currentPage,toastTimer,saved=[],gallery=[],galleryIndex=0,zoom=1,lastFocus,libraryLimit=24,selectedSheet=0,homeGroup='All';
try{const s=JSON.parse(localStorage.getItem('coolex-shortlist')||'[]');saved=Array.isArray(s)?s.filter(x=>typeof x==='string'):[]}catch{}
const isSaved=path=>saved.includes(path);
const countText=p=>t('count.sheets',{count:p.catalogues.length})+(p.videos.length?' · '+t('count.videos',{count:p.videos.length}):'');
const empty=(title,desc,action=t('filter.reset'),act='reset-filters')=>`<div class="empty"><h2>${escape(title)}</h2><p>${escape(desc)}</p><button class="btn btn-dark" data-action="${act}">${escape(action)}${icon('arrow')}</button></div>`;
function announce(s){$('#announcer').textContent=s}
function toast(s,link=false){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.innerHTML=escape(s)+(link?` <a href="/Coolex/shortlist">${escape(t('shortlist.view'))}</a>`:'');document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4500)}
function videoCategory(video) {
  return video.page === '/' ? t('media.showroom') : pageTitle(PAGES.find(page => page.path === video.page));
}
function videoTitle(video) {
  if (video.id === 'HNmqwMWeGDA') return t('media.tour');
  const generated = video.title.match(/ · demonstration (\d+)$/);
  return generated ? t('media.demonstration', {title: videoCategory(video), index: generated[1]}) : video.title;
}
function videoSearchText(video) {
  const page = PAGES.find(page => page.path === video.page);
  return [video.title, videoTitle(video), page ? I18n.searchText(page) : '', video.group].join(' ');
}
function renderLanguageControl() {
  const root = languageRoot;
  const menu=$('#menu-dialog');
  const target=menu.open||mobileNavigation.matches?$('#menu-language-slot'):$('#navbar-language-slot');
  if(!target){root.remove();return}
  target.append(root);
  if (!root.firstElementChild) {
    root.innerHTML = `<div class="language-control" role="group"><span class="language-thumb" aria-hidden="true"></span>${Object.entries(I18n.languages).map(([code,label]) => `<button type="button" data-locale="${code}" lang="${code}" aria-pressed="false">${escape(label)}</button>`).join('')}</div>`;
  }
  const control = $('.language-control',root);
  control.setAttribute('aria-label',t('language.choose'));
  control.style.setProperty('--language-index',Object.keys(I18n.languages).indexOf(I18n.locale));
  $$('[data-locale]',root).forEach(button => button.setAttribute('aria-pressed',String(button.dataset.locale===I18n.locale)));
}
function chooseLanguage(language, persist = true) {
  if (language === I18n.locale) return;
  if (!I18n.choose(language,persist)) { toast(t('language.unavailable')); return; }
  const scroll = window.scrollY;
  const menuWasOpen=$('#menu-dialog').open;
  const openDetails = $$('details').flatMap((item,index) => item.open?[index]:[]);
  render();
  if(menuWasOpen)openMenu();
  $$('details').forEach((item,index) => {item.open=openDetails.includes(index)});
  window.scrollTo({top:scroll,behavior:'instant'});
  $(`[data-locale="${language}"]`)?.focus({preventScroll:true});
  announce(t('language.changed',{language:I18n.languages[language]}));
}
function applyHomeGroup(group, notify = true) {
  homeGroup = group;
  $$('[data-home-group]').forEach(button => {
    const active = button.dataset.homeGroup === group;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
  });
  const paths=['/fryers','/soft-icecream-machines','/pizzaovens','/popcornmachine','/milkboilers-coffeebrewer-teabrewer','/waffle','/cooling-juice-dispensers','/westerndeepfreezers'];
  const list=group==='All'?paths.map(path=>EQUIPMENT.find(page=>page.path===path)):EQUIPMENT.filter(page=>page.group===group).slice(0,8);
  $('#featured-grid').innerHTML=list.map(equipmentCard).join('');
  if(notify) announce(t('results.displayed',{count:list.length}));
}

let heritageObserver;
function selectedHeritagePage(){
  const id=new URLSearchParams(location.search).get('page')||'landing';
  return DATA.heritage.pages.find(page=>page.id===id)||DATA.heritage.pages[0];
}
function heritageTeaser(){return `<section class="section wrap"><div class="heritage-teaser"><div class="heritage-teaser-copy"><p class="eyebrow">${escape(t('heritage.eyebrow'))}</p><h2>${escape(t('heritage.teaser_title'))}</h2><p>${escape(t('heritage.teaser_note'))}</p><a class="text-link" href="/Coolex/heritage">${escape(t('heritage.explore'))} ${icon('arrow')}</a><span class="heritage-edition">coolexworld.com · ${escape(t('heritage.classic'))}</span></div><div class="heritage-mini-browser"><div class="heritage-browser-bar"><span class="heritage-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>coolexworld.com/</span>${icon('clock')}</div><div class="heritage-preview" data-archive-preview><iframe src="/Coolex/heritage/archive/landing-preview.htm" title="${escape(t('heritage.preview'))}" sandbox="" loading="lazy" tabindex="-1" aria-hidden="true" inert></iframe><a class="heritage-preview-link" href="/Coolex/heritage" aria-label="${escape(t('heritage.explore'))}"><span class="heritage-preview-badge">${escape(t('heritage.open_capsule'))} ${icon('diagonal')}</span></a></div></div></div></section>`}
function heritagePage(){
 const page=selectedHeritagePage();const original=new URLSearchParams(location.search).get('size')==='original';
 return frame(`<section class="page-intro wrap heritage-intro" id="top">${breadcrumb([{name:t('heritage.title')}])}<p class="eyebrow">${escape(t('heritage.eyebrow'))}</p><h1>${escape(t('heritage.title'))}<span style="color:var(--red)">.</span></h1><p>${escape(t('heritage.description'))}</p></section><section class="wrap heritage-exhibit"><div class="heritage-chapters" role="group" aria-label="${escape(t('heritage.choose_page'))}">${DATA.heritage.pages.map((item,index)=>`<button class="heritage-chapter" data-heritage-page="${item.id}" aria-pressed="${item.id===page.id}"><small>${String(index+1).padStart(2,'0')}</small><span>${escape(t('heritage.page.'+item.id))}</span>${icon('arrow')}</button>`).join('')}</div><div class="heritage-context"><span class="heritage-context-mark">${icon('clock')}</span><p>${escape(t('heritage.historical_note'))}</p><a href="/Coolex/contact-details">${escape(t('heritage.current_site'))} ${icon('diagonal')}</a></div><div class="heritage-browser"><div class="heritage-browser-bar"><span class="heritage-dots" aria-hidden="true"><i></i><i></i><i></i></span><span id="heritage-address">${escape(page.sourceUrl.replace('https://',''))}</span><span class="heritage-saved">${escape(t('heritage.saved',{date:heritageDate()}))}</span></div><div class="heritage-tools"><div><h2 id="heritage-page-title">${escape(t('heritage.page.'+page.id))}</h2><p id="heritage-page-note">${escape(t('heritage.note.'+page.id))}</p></div><div class="heritage-view-actions"><div class="heritage-size-control" role="group" aria-label="${escape(t('heritage.view_size'))}"><button data-heritage-size="fit" aria-pressed="${!original}">${escape(t('heritage.fit'))}</button><button data-heritage-size="original" aria-pressed="${original}">${escape(t('heritage.original_size'))}</button></div><a id="heritage-source" class="text-link" href="${escape(page.sourceUrl)}" target="_blank" rel="noopener noreferrer">${escape(t('heritage.source'))} ${icon('diagonal')}</a></div></div><div class="heritage-surface ${original?'original-size':''}" id="heritage-surface"><iframe id="heritage-frame" src="${page.archiveUrl}" title="${escape(t('heritage.frame_title',{page:t('heritage.page.'+page.id)}))}" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="heritage-browser-footer"><span>${escape(t('heritage.scroll_hint'))}</span><span>${escape(t('heritage.page_count',{count:DATA.heritage.pages.length}))}</span></div></div><details class="heritage-details"><summary>${escape(t('heritage.preservation'))}</summary><div><p>${escape(t('heritage.preservation_note',{count:DATA.heritage.assetCount}))}</p><p>${escape(t('heritage.date_note'))}</p></div></details>${cta()}</section>`);
}
function heritageDate(){return new Intl.DateTimeFormat(I18n.locale,{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date(DATA.heritage.capturedDate+'T12:00:00+05:30'))}
function layoutHeritageFrames(){
 heritageObserver?.disconnect();
 const resize=()=>{
  $$('[data-archive-preview]').forEach(surface=>{const iframe=$('iframe',surface);iframe.style.width='1120px';iframe.style.height='850px';iframe.style.transform=`scale(${surface.clientWidth/1120})`});
  const surface=$('#heritage-surface'),iframe=$('#heritage-frame');if(!surface||!iframe)return;
  const original=surface.classList.contains('original-size');if(!original)surface.scrollLeft=0;const scale=original?1:Math.min(1,surface.clientWidth/1120);
  iframe.style.width=Math.max(1120,original?surface.clientWidth:1120)+'px';iframe.style.height=(surface.clientHeight/scale)+'px';iframe.style.transform=`scale(${scale})`;iframe.style.marginLeft=(!original&&surface.clientWidth>1120?(surface.clientWidth-1120)/2:0)+'px';
 };
 heritageObserver=new ResizeObserver(resize);$$('[data-archive-preview],#heritage-surface').forEach(surface=>heritageObserver.observe(surface));resize();
}
function selectHeritagePage(id,fromFrame=false){
 const page=DATA.heritage.pages.find(item=>item.id===id);if(!page||!$('#heritage-frame'))return;
 const query=new URLSearchParams(location.search);query.set('page',id);history.replaceState(null,'',location.pathname+'?'+query);
 $$('[data-heritage-page]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.heritagePage===id)));
 $('#heritage-address').textContent=page.sourceUrl.replace('https://','');$('#heritage-page-title').textContent=t('heritage.page.'+id);$('#heritage-page-note').textContent=t('heritage.note.'+id);$('#heritage-source').href=page.sourceUrl;
 const iframe=$('#heritage-frame');iframe.title=t('heritage.frame_title',{page:t('heritage.page.'+id)});if(!fromFrame)iframe.src=page.archiveUrl;
 announce(t('heritage.viewing',{page:t('heritage.page.'+id)}));
}
function setHeritageSize(size){
 if(!['fit','original'].includes(size))return;
 const query=new URLSearchParams(location.search);if(size==='original')query.set('size',size);else query.delete('size');history.replaceState(null,'',location.pathname+(query.size?'?'+query:''));
 $('#heritage-surface').classList.toggle('original-size',size==='original');$$('[data-heritage-size]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.heritageSize===size)));layoutHeritageFrames();
}
window.addEventListener('message',event=>{
 const frame=$('#heritage-frame');if(!frame||event.source!==frame.contentWindow||event.data?.type!=='coolex-archive-page')return;
 selectHeritagePage(event.data.id,true);
});

function header(active){return `<div class="utility"><div class="wrap"><span><i class="dot"></i>${escape(t('brand.trade'))}</span><div class="right"><a href="/Coolex/contact-details">${escape(t('brand.locations'))} ${icon('diagonal')}</a><a href="${channels.telugu}" target="_blank" rel="noopener noreferrer">${escape(t('youtube.watch_telugu'))} ${icon('play')}</a></div></div></div><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/Coolex/" aria-label="${escape(t('brand.home'))}"><img src="${DATA.logo}" width="112" height="68" alt="${escape(t('brand.logo_alt'))}"></a><nav class="desktop-nav" aria-label="${escape(t('nav.main'))}">${[[t('nav.equipment'),'/catalog','equipment'],[t('nav.watch'),'/videos','videos'],[t('nav.ideas'),'/business-ideas','ideas'],[t('nav.showrooms'),'/contact-details','contact']].map(([name,url,id])=>`<a href="${siteUrl(url)}" ${active===id?'aria-current="page"':''}>${escape(name)}</a>`).join('')}</nav><div class="header-actions"><div id="navbar-language-slot" class="navbar-language-slot"></div><button class="icon-btn header-search" data-action="search" aria-label="${escape(t('search.label'))}">${icon('search')}<span>${escape(t('search.short'))}</span><kbd>/</kbd></button><a class="icon-btn" href="/Coolex/shortlist" aria-label="${escape(saved.length?t('shortlist.header_count',{count:saved.length}):t('nav.shortlist'))}">${icon('bookmark')}<span class="sr-only" data-saved-count>${saved.length}</span></a>${button(t('action.talk'),'btn-red btn-small',tel,'diagonal')}<button class="icon-btn mobile-toggle" data-action="menu" aria-label="${escape(t('nav.open'))}">${icon('menu')}</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div><a href="/Coolex/" class="footer-wordmark">COOLEX<span style="color:var(--yellow)">.</span></a><p>${escape(t('footer.tagline'))}<br>${escape(t('footer.ideas'))}</p><a class="footer-phone" href="${tel}">${phone} ${icon('diagonal')}</a></div><div><h3>${escape(t('footer.find'))}</h3><div class="footer-links"><a href="/Coolex/catalog">${escape(t('footer.catalogue'))}</a><a href="/Coolex/videos">${escape(t('footer.videos'))}</a><a href="/Coolex/business-ideas">${escape(t('footer.ideas_link'))}</a><a href="/Coolex/shortlist">${escape(t('nav.shortlist'))}</a><a href="/Coolex/heritage">${escape(t('heritage.footer'))}</a></div></div><div><h3>${escape(t('footer.hello'))}</h3><div class="footer-links"><a href="/Coolex/contact-details">${escape(t('brand.locations'))} ${icon('diagonal')}</a><a href="${channels.telugu}" target="_blank" rel="noopener noreferrer">${escape(t('youtube.telugu'))} ${icon('diagonal')}</a><a href="${channels.english}" target="_blank" rel="noopener noreferrer">${escape(t('youtube.hindi_english'))} ${icon('diagonal')}</a></div><p>${escape(t('footer.hours'))}</p></div></div><div class="footer-bottom"><span>${escape(t('brand.company_since'))}</span><span>${escape(t('footer.disclaimer'))}</span><a href="#top">${escape(t('footer.top'))}</a></div></div></footer>`}
function frame(content,active=''){return header(active)+`<main id="main" tabindex="-1">${content}</main>`+footer()}
const breadcrumb=items=>`<nav class="breadcrumb" aria-label="${escape(t('access.breadcrumb'))}"><a href="/Coolex/">${escape(t('nav.home'))}</a>${items.map(x=>`${icon('chevron')}${x.href?`<a href="${escape(siteUrl(x.href))}">${escape(x.name)}</a>`:`<span aria-current="page">${escape(x.name)}</span>`}`).join('')}</nav>`;
function equipmentCard(p){const art=!p.photos.length;return `<article class="equipment-card"><a href="${siteUrl(p.path)}" class="card-image${art?' art':''}" tabindex="-1" aria-hidden="true"><img src="${escape(p.thumbnail)}" width="400" height="300" alt="" loading="lazy" decoding="async"></a><button class="icon-btn save-card" data-save="${p.path}" aria-label="${escape(t(isSaved(p.path)?'shortlist.remove_label':'shortlist.save_label',{title:pageTitle(p)}))}" aria-pressed="${isSaved(p.path)}">${icon(isSaved(p.path)?'check':'bookmark')}</button><span class="card-group">${escape(groupTitle(p.group))}</span><h3><a class="card-title" href="${siteUrl(p.path)}">${escape(pageTitle(p))}${icon('diagonal')}</a></h3><p class="card-meta">${countText(p)}</p></article>`}
function videoCard(v,library=false){return `<div class="video-entry"><button class="video-card" data-video="${escape(v.key)}" aria-label="${escape(t('media.play',{title:videoTitle(v)}))}"><div class="video-cover"><img src="${escape(v.poster)}" width="480" height="300" alt="" loading="lazy"><span class="play-circle">${icon('play')}</span><span class="video-label">${v.type==='local'?t('media.video'):'YouTube'} ${v.start?'· '+escape(t('media.from',{time:Math.floor(v.start/60)+':'+String(v.start%60).padStart(2,'0')})):''}</span></div>${library?'':`<span class="library-category">${escape(videoCategory(v))}</span>`}<h3>${escape(videoTitle(v))}</h3></button>${library?`<a class="library-category" href="${escape(siteUrl(v.page))}">${escape(videoCategory(v))} ${icon('diagonal')}</a>`:''}</div>`}
function ideaCard(p){return `<a href="${siteUrl(p.path)}" class="idea-card"><img src="${escape(p.tile?.src||p.catalogues[0]?.src||p.thumbnail)}" alt="${escape(t('ideas.collection_alt',{title:pageTitle(p)}))}" loading="lazy" width="500" height="300"><div class="idea-info"><div><h3>${escape(pageTitle(p))}</h3><small>${p.photos.length?t('ideas.photos'):p.videos.length?t('ideas.demos'):t('ideas.menu_link')}</small></div>${icon('diagonal')}</div></a>`}
function cta(){return `<div class="page-cta"><div><h2>${escape(t('cta.title'))}</h2><p>${escape(t('cta.note'))}</p></div>${button(t('action.talk_showroom'),'btn-dark',tel,'phone')}</div>`}
function homeArtwork(){return ['/fryers','/waffle','/soft-icecream-machines'].map(path=>EQUIPMENT.find(p=>p.path===path)?.catalogues[0]).filter(Boolean)}
function homePage(){const featured=['/fryers','/soft-icecream-machines','/pizzaovens','/popcornmachine','/milkboilers-coffeebrewer-teabrewer','/waffle','/cooling-juice-dispensers','/westerndeepfreezers'].map(x=>EQUIPMENT.find(p=>p.path===x));const tour=VIDEO_LIBRARY.find(v=>v.id==='HNmqwMWeGDA')||VIDEO_LIBRARY.find(v=>v.page==='/');const demos=['/fryers','/soft-icecream-machines','/pizzaovens'].map(path=>VIDEO_LIBRARY.find(v=>v.page===path)).filter(Boolean);
return frame(`<section class="hero" id="top"><div class="wrap hero-grid"><div><p class="eyebrow">${escape(t('home.eyebrow'))}</p><h1>${escape(t('home.big_ideas'))}<br>${escape(t('home.equipment'))}<br><em>${escape(t('home.cooking'))}</em></h1><p class="hero-copy">${escape(t('home.description'))}</p><div class="hero-actions">${button(t('action.explore_equipment'))}${button(t('action.visit'),'btn-outline','/contact-details','pin')}</div><p class="hero-note">${escape(t('home.note'))}</p></div><div class="hero-visual"><img class="hero-photo" src="${DATA.hero}" alt="${escape(t('home.hero_alt'))}" width="1500" height="1100" fetchpriority="high"><span class="since-stamp">${escape(t('home.stamp'))}<strong>1975</strong>${escape(t('home.stamp_since'))}</span><button class="tour-float" data-video="${tour?.key||''}"><span class="play-circle">${icon('play')}</span><span><strong>${escape(t('home.tour'))}</strong><small>${escape(t('home.tour_note'))}</small></span><span class="arrow">${icon('diagonal')}</span></button></div></div></section><div class="proof-strip"><div class="wrap proof-grid">${[['grid',t('home.category_count'),t('home.kind_machine')],['play',t('home.see_first'),t('home.video_proof')],['pin',t('home.locations'),t('brand.locations')],['sun',t('brand.since'),t('home.familiar')]].map(([i,t,d])=>`<div class="proof-item">${icon(i)}<div><strong>${escape(t)}</strong><small>${escape(d)}</small></div></div>`).join('')}</div></div><section class="section wrap" id="equipment"><div class="section-head"><div><p class="eyebrow">${escape(t('footer.find'))}</p><h2>${escape(t('home.menu'))}</h2><p>${escape(t('home.menu_note'))}</p></div><a class="text-link" href="/Coolex/catalog">${escape(t('action.all_equipment'))} ${icon('arrow')}</a></div><div class="chip-row home-chips"><button class="chip active" data-home-group="All" aria-pressed="true">${escape(t('home.everything'))}</button>${DATA.groups.map(g=>`<button class="chip" data-home-group="${escape(g)}" aria-pressed="false">${escape(groupTitle(g))}</button>`).join('')}</div><div class="equipment-grid" id="featured-grid">${featured.map(equipmentCard).join('')}</div><div class="explore-panel">${icon('search')}<span>${escape(t('home.search_prompt'))}</span><button class="text-link" style="background:transparent;border-top:0;border-right:0;border-left:0" data-action="search">${escape(t('search.label'))} ${icon('arrow')}</button></div></section><section class="section dark-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">${escape(t('home.less_guessing'))}</p><h2>${escape(t('home.see_machines'))}<br>${escape(t('home.possibilities'))}</h2><p>${escape(t('home.video_note'))}</p></div><a class="text-link" href="/Coolex/videos">${escape(t('action.explore_videos'))} ${icon('arrow')}</a></div><div class="video-grid home-video-grid">${demos.map(v=>videoCard(v)).join('')}</div></div></section><section class="section wrap"><div class="ideas-layout"><div class="ideas-copy"><div><p class="eyebrow">${escape(t('home.inspiration'))}</p><h2>${escape(t('home.next_business'))}<br>${escape(t('home.start_here'))}</h2></div><div><p>${escape(t('home.ideas_note'))}</p><a class="text-link" href="/Coolex/business-ideas">${escape(t('action.explore_ideas'))} ${icon('arrow')}</a></div></div><div class="idea-cards">${['/chicxpress-fried-chicken-franchise','/copy-of-fresh-drink-outlet-menu'].map(path=>ideaCard(CONCEPTS.find(p=>p.path===path))).join('')}</div></div></section>${showroomSection()}${heritageTeaser()}<section class="section wrap"><div class="section-head"><div><p class="eyebrow">${escape(t('home.originals'))}</p><h2>${escape(t('home.familiar_catalogue'))}<br>${escape(t('home.clearer'))}</h2></div></div><div class="catalogue-art-grid">${homeArtwork().map((im,i)=>`<button class="photo-button" data-gallery="home-art" data-index="${i}" aria-label="${escape(t('home.view_artwork',{index:i+1}))}"><img src="${im.src}" alt="${escape(t('home.artwork',{index:i+1}))}" loading="lazy"><span>${icon('expand')}</span></button>`).join('')}</div><details class="details-collapsible"><summary>${escape(t('home.all_originals'))}</summary><div class="photo-grid">${[...HOME.photos,...HOME.catalogues,...HOME.navigationArtwork].map((im,i)=>photoTile(im,i,'home-all')).join('')}</div></details>${cta()}</section>`)}
function showroomSection(){return `<section class="showroom-section"><div class="wrap showroom-layout"><img class="showroom-image" src="/Coolex/assets/showroom-colour.jpg" width="1000" height="800" alt="${escape(t('showroom.photo_alt'))}" loading="lazy"><div><p class="eyebrow">${escape(t('showroom.eyebrow'))}</p><h2>${escape(t('showroom.screen'))}<br>${escape(t('showroom.destination'))}</h2><p>${escape(t('showroom.note'))}</p><div class="location-rows"><div class="location-row"><div><strong>${escape(t('location.vijayawada'))}</strong><small>${escape(t('location.ap'))}</small></div><a href="${maps.vijayawada}" target="_blank" rel="noopener noreferrer">${escape(t('action.directions'))} ${icon('diagonal')}</a></div><div class="location-row"><div><strong>${escape(t('location.secunderabad'))}</strong><small>${escape(t('location.telangana'))}</small></div><a href="${maps.hyderabad}" target="_blank" rel="noopener noreferrer">${escape(t('action.directions'))} ${icon('diagonal')}</a></div></div><a class="text-link" href="/Coolex/contact-details">${escape(t('action.plan_visit'))} ${icon('arrow')}</a></div></div></section>`}
function directoryPage(){return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:t('nav.equipment')}])}<p class="eyebrow">${escape(t('catalogue.eyebrow'))}</p><h1>${I18n.locale==='en'?`${escape(t('catalogue.find'))}<br>${escape(t('catalogue.of'))} <span style="color:var(--red)">${escape(t('catalogue.equipment'))}</span>`:escape(t('catalogue.heading'))}</h1><p>${escape(t('catalogue.description'))}</p></section><section class="directory-section wrap">${directoryControls('equipment')}<div class="result-bar"><p id="result-count" role="status"></p><button data-action="reset-filters">${escape(t('filter.reset'))}</button></div><div class="equipment-grid" id="directory-grid"></div><div class="special-enquiry">${[[t('catalogue.western'),'img_comp-m5b0ag1z'],[t('catalogue.celfrost'),'img_comp-m5b3f69c']].map(([dealerTitle,id])=>{const im=HOME.catalogues.find(im=>im.alt.toLowerCase().includes((id==='img_comp-m5b0ag1z'?'Western':'Celfrost').toLowerCase()));return `<a href="/Coolex/contact-details">${im?`<img src="${im.src}" alt="" loading="lazy">`:icon('phone')}<div><h3>${escape(I18n.t('catalogue.looking_for',{name:dealerTitle}))}</h3><small>${escape(t('catalogue.contact_note'))} ${icon('arrow')}</small></div></a>`}).join('')}</div>${cta()}</section>`,'equipment')}
function directoryControls(type){const groups=type==='videos'?['All',...DATA.groups,'Business ideas','Showrooms']:['All',...DATA.groups];return `<div class="directory-toolbar"><div class="field-search">${icon('search')}<label class="sr-only" for="directory-search">${escape(t(type==='videos'?'search.videos':'search.label'))}</label><input id="directory-search" type="search" placeholder="${escape(t(type==='videos'?'search.video_placeholder':'search.placeholder'))}" autocomplete="off"><button class="clear-search" data-action="clear-directory" aria-label="${escape(t('filter.clear'))}">${icon('close')}</button></div>${type==='equipment'?`<label class="sr-only" for="sort-order">${escape(t('sort.label'))}</label><select class="sort-select" id="sort-order"><option value="featured">${escape(t('sort.featured'))}</option><option value="az">${escape(t('sort.az'))}</option><option value="za">${escape(t('sort.za'))}</option></select>`:''}</div><div class="chip-row" id="directory-groups" role="group" aria-label="${escape(t('filter.family'))}">${groups.map(group=>`<button class="chip" data-group="${escape(group)}" aria-pressed="${group==='All'}">${escape(groupTitle(group))}${group==='All'?'':`<small>${type==='videos'?VIDEO_LIBRARY.filter(v=>v.group===group).length:EQUIPMENT.filter(p=>p.group===group).length}</small>`}</button>`).join('')}</div>`}
function normalize(s){return s.normalize('NFKC').toLocaleLowerCase(I18n.locale).replace(/sandwitch/g,'sandwich').replace(/icecreams?/g,'ice cream').replace(/orenge/g,'orange').replace(/[^\p{L}\p{M}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim()}
function matches(text,q){const t=normalize(text);return normalize(q).split(' ').filter(Boolean).every(w=>t.includes(w.replace(/s$/,'')))}
function getFilters(){const q=new URLSearchParams(location.search);return {q:q.get('q')||'',group:q.get('group')||'All',sort:q.get('sort')||'featured'}}
function setFilters(patch){const p=new URLSearchParams(location.search);for(const[k,v]of Object.entries(patch)){if(!v||v==='All'||v==='featured')p.delete(k);else p.set(k,v)}history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash);libraryLimit=24;updateDirectory()}
function updateDirectory(){const mode=currentPath()==='/videos'?'videos':'equipment';const f=getFilters();const field=$('#directory-search');if(!field)return;if(field.value!==f.q)field.value=f.q;if($('#sort-order'))$('#sort-order').value=f.sort;$$('[data-group]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.group===f.group)));const base=mode==='videos'?VIDEO_LIBRARY:EQUIPMENT;let list=(mode==='equipment'&&f.q&&f.group==='All'?[...base,...CONCEPTS]:base).filter(p=>(f.group==='All'||p.group===f.group)&&matches(mode==='videos'?videoSearchText(p):I18n.searchText(p),f.q));if(mode==='equipment'&&f.sort!=='featured')list.sort((a,b)=>pageTitle(a).localeCompare(pageTitle(b),I18n.locale)*(f.sort==='za'?-1:1));if(mode==='equipment'&&f.sort==='featured')list.sort((a,b)=>equipmentOrder(a)-equipmentOrder(b));$('#result-count').textContent=t(mode==='videos'?'results.videos':'results.categories',{count:list.length})+(f.q?' '+t('results.query',{query:f.q}):'')+(f.group!=='All'?' · '+groupTitle(f.group):'');$('#directory-grid').innerHTML=list.length?list.slice(0,mode==='videos'?libraryLimit:1000).map(mode==='videos'?v=>videoCard(v,true):equipmentCard).join(''):empty(t('empty.title'),t('empty.note'));$('#more-videos')?.remove();if(mode==='videos'&&list.length>libraryLimit){const d=document.createElement('div');d.id='more-videos';d.className='load-more';d.innerHTML=`<button class="btn btn-outline" data-action="more-videos">${escape(t('library.more',{count:list.length-libraryLimit}))} ${icon('plus')}</button>`;$('#directory-grid').after(d)}}
function equipmentOrder(p){const order=['/fryers','/pizzaovens','/sandwitchgriller','/waffle','/griddles','/popcornmachine'];return order.includes(p.path)?order.indexOf(p.path):10+DATA.groups.indexOf(p.group)*100+EQUIPMENT.indexOf(p)}
function videosPage(){return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:t('nav.watch')}])}<p class="eyebrow">${escape(t('library.eyebrow'))}</p><h1>${escape(t('library.play'))}<br>${escape(t('library.possibilities'))}</h1><p>${escape(t('library.description'))}</p></section><section class="directory-section wrap">${directoryControls('videos')}<div class="result-bar"><p id="result-count" role="status"></p><button data-action="reset-filters">${escape(t('filter.reset'))}</button></div><div class="video-grid filtered-video-grid" id="directory-grid"></div><p class="media-note">${escape(t('library.note'))}</p>${cta()}</section>`,'videos')}
function photoTile(im,i,key='photos'){const title=currentPage?pageTitle(currentPage):t('media.showroom');return `<button class="photo-button" data-gallery="${escape(key)}" data-index="${i}" aria-label="${escape(t('media.enlarge_photo',{title,index:i+1}))}"><img src="${escape(im.preview||im.src)}" width="520" height="390" alt="${escape(t('media.photo_alt',{title,index:i+1}))}" loading="lazy"><span>${icon('expand')}</span></button>`}
function detailPage(p){let tabs=[['catalogues',p.catalogues.length,p.kind==='concept'?t('media.collection'):t('media.catalogues')],['photos',p.photos.length,t('media.photos')],['videos',p.videos.length,t('media.videos')]].filter(t=>t[1]);const wanted=new URLSearchParams(location.search).get('view');let selected=tabs.find(t=>t[0]===wanted)?.[0]||tabs[0]?.[0];return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:p.kind==='concept'?t('nav.ideas'):t('nav.equipment'),href:p.kind==='concept'?'/business-ideas':'/catalog'},{name:pageTitle(p)}])}<div class="detail-intro"><div><p class="eyebrow">${escape(groupTitle(p.group))}</p><h1>${escape(pageTitle(p))}<span style="color:var(--red)">.</span></h1><p>${escape(I18n.description(p))}</p></div><aside class="detail-summary"><p>${escape(t('media.summary'))}</p><button class="btn btn-outline" data-save="${p.path}" aria-pressed="${isSaved(p.path)}">${icon(isSaved(p.path)?'check':'bookmark')}<span>${isSaved(p.path)?t('shortlist.saved'):t('shortlist.save')}</span></button>${button(t('action.ask_range'),'btn-red',tel,'phone')}</aside></div></section><section class="media-section wrap"><div class="tabs" role="tablist" aria-label="${escape(t('media.tabs_label',{title:pageTitle(p)}))}">${tabs.map(([id,n,label])=>`<button id="tab-${id}" class="tab" role="tab" data-tab="${id}" aria-selected="${selected===id}" aria-controls="detail-panel" tabindex="${selected===id?0:-1}">${label}<span>${n}</span></button>`).join('')}</div><div id="detail-panel" role="tabpanel" aria-labelledby="tab-${selected}" tabindex="0">${mediaPanel(p,selected)}</div><p class="media-note">${escape(t('media.disclaimer'))}</p>${cta()}</section>${related(p)}`,p.kind==='concept'?'ideas':'equipment')}
function mediaPanel(p,selected){if(selected==='catalogues'){return `<div class="catalogue-layout"><aside class="sheet-sidebar"><p>${p.kind==='concept'?t('media.original_collection'):t('media.sheets')} · ${p.catalogues.length}</p><div class="sheet-list">${p.catalogues.map((im,i)=>`<button class="sheet-thumb" data-sheet="${i}" aria-pressed="${i===selectedSheet}" aria-label="${escape(t('media.view_sheet',{index:i+1}))}"><img src="${escape(im.preview||im.src)}" alt="" loading="lazy"><span><strong>${escape(t('media.sheet_label',{index:String(i+1).padStart(2,'0')}))}</strong><small>${escape(t('media.original_artwork'))}</small></span></button>`).join('')}</div></aside><div class="sheet-stage" id="sheet-stage">${sheetStage(p,Math.min(selectedSheet,p.catalogues.length-1))}</div></div>`}if(selected==='photos')return `<div class="gallery-note"><p>${escape(t('media.photo_note'))}</p><p>${escape(t('media.photo_count',{count:p.photos.length}))}</p></div><div class="photo-grid">${p.photos.map((im,i)=>photoTile(im,i)).join('')}</div>`;if(selected==='videos')return `<div class="video-grid">${p.videos.map(v=>videoCard(v)).join('')}</div><p class="media-note">${escape(t('media.video_note'))}</p>`;return empty(t('media.empty_title'),t('media.empty_note'),t('action.explore_equipment'),'catalog')}
function sheetStage(p,i){const im=p.catalogues[i];return `<div class="sheet-tools"><span>${escape(t('media.sheet_count',{index:i+1,count:p.catalogues.length}))}</span><button class="icon-btn" data-sheet="${i-1}" aria-label="${escape(t('media.previous_sheet'))}" ${i===0?'disabled':''}>${icon('left')}</button><button class="icon-btn" data-sheet="${i+1}" aria-label="${escape(t('media.next_sheet'))}" ${i===p.catalogues.length-1?'disabled':''}>${icon('chevron')}</button><button class="btn btn-dark" data-gallery="catalogues" data-index="${i}">${icon('expand')}${escape(t('media.enlarge'))}</button></div><button class="sheet-open" data-gallery="catalogues" data-index="${i}" aria-label="${escape(t('media.enlarge_sheet',{index:i+1}))}"><img src="${escape(im.src)}" alt="${escape(t('media.sheet_alt',{title:pageTitle(p),index:i+1}))}"></button>`}
function related(p){let list=(p.kind==='concept'?CONCEPTS:EQUIPMENT).filter(x=>x.path!==p.path&&(p.kind==='concept'||x.group===p.group)).slice(0,4);if(list.length<4&&p.kind==='equipment')list.push(...EQUIPMENT.filter(x=>!list.includes(x)&&x.path!==p.path).slice(0,4-list.length));return `<section class="related-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">${escape(t('related.eyebrow'))}</p><h2>${p.kind==='concept'?t('related.ideas'):t('related.equipment')}</h2></div></div><div class="${p.kind==='concept'?'idea-cards concepts-page':'equipment-grid'}">${list.map(p.kind==='concept'?ideaCard:equipmentCard).join('')}</div></div></section>`}
function ideasPage(){return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:t('nav.ideas')}])}<p class="eyebrow">${escape(t('ideas.eyebrow'))}</p><h1>${escape(t('ideas.menu'))}<br>${escape(t('ideas.possibility'))}</h1><p>${escape(t('ideas.description'))}</p></section><section class="wrap section-end"><div class="idea-cards concepts-page">${CONCEPTS.map(ideaCard).join('')}</div>${cta()}</section>`,'ideas')}
function contactPage(){return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:t('nav.showrooms')}])}<p class="eyebrow">${escape(t('contact.eyebrow'))}</p><h1>${escape(t('contact.good_things'))}<br>${escape(t('contact.conversation'))}</h1><p>${escape(t('contact.description'))}</p></section><section class="wrap section-end"><div class="contact-grid"><article class="contact-card"><span class="city-number">01 / ${escape(t('location.ap'))}</span><h2>${escape(t('location.vijayawada'))}.</h2><p>${escape(t('contact.vijayawada'))}</p><div class="contact-actions">${button('9848887467','btn-red',tel,'phone')}${button(t('action.directions'),'btn-outline',maps.vijayawada,'diagonal')}</div><div class="contact-meta"><span>${escape(t('brand.company'))}</span><span>${escape(t('location.vijayawada_state'))}</span></div></article><article class="contact-card"><span class="city-number">02 / ${escape(t('location.telangana'))}</span><h2>${escape(t('location.hyderabad'))}.</h2><p>${escape(t('contact.hyderabad'))}</p><div class="contact-actions">${button('9848115355','btn-red','tel:+919848115355','phone')}${button(t('action.directions'),'btn-outline',maps.hyderabad,'diagonal')}</div><div class="contact-meta"><span>${escape(t('brand.company'))}</span><span>${escape(t('location.secunderabad_state'))}</span></div></article></div><div class="contact-banner"><img src="/Coolex/assets/showroom-wide.jpg" alt="${escape(t('contact.photo_alt'))}" width="1100" height="700" loading="lazy"><div><p class="eyebrow">${escape(t('action.plan_visit'))}</p><h2>${escape(t('contact.questions'))}<br>${escape(t('contact.ideas'))}</h2><p>${escape(t('contact.hours'))}</p><p>${escape(t('contact.shortlist'))}</p><a href="/Coolex/shortlist" class="text-link">${escape(t('action.open_shortlist'))} ${icon('arrow')}</a></div></div><div class="section-head"><div><p class="eyebrow">${escape(t('contact.discover'))}</p><h2>${escape(t('contact.language'))}</h2><p>${escape(t('contact.channels'))}</p></div></div><div class="contact-actions">${button(t('youtube.telugu'),'btn-outline',channels.telugu,'play')}${button(t('youtube.hindi_english'),'btn-outline',channels.english,'play')}</div></section>`,'contact')}
function shortlistPage(){const list=PAGES.filter(p=>isSaved(p.path));return frame(`<section class="page-intro wrap" id="top">${breadcrumb([{name:t('nav.shortlist')}])}<p class="eyebrow">${escape(t('shortlist.eyebrow'))}</p><h1>${escape(t('shortlist.idea'))}<br>${escape(t('shortlist.shape'))}</h1><p>${escape(t('shortlist.description'))}</p></section><section class="wrap section-end" id="shortlist-content">${list.length?`<div class="result-bar"><p>${escape(t('shortlist.count',{count:list.length}))}</p></div><div class="shortlist-list">${list.map(p=>`<article class="shortlist-row"><img src="${escape(p.thumbnail)}" alt="" width="90" height="80"><div><small>${escape(groupTitle(p.group))}</small><h2><a href="${siteUrl(p.path)}">${escape(pageTitle(p))}</a></h2><a class="text-link" style="font-size:.7rem" href="${siteUrl(p.path)}">${escape(t('action.explore_category'))} ${icon('arrow')}</a></div><button class="icon-btn" data-save="${p.path}" aria-label="${escape(t('shortlist.remove_label',{title:pageTitle(p)}))}">${icon('trash')}</button></article>`).join('')}</div><div class="shortlist-actions"><button class="btn btn-dark" data-action="copy-shortlist">${icon('copy')}${escape(t('shortlist.copy'))}</button>${button(t('action.call_showroom'),'btn-red',tel,'phone')}<p>${escape(t('shortlist.nothing_sent'))}</p></div>`:empty(t('shortlist.empty_title'),t('shortlist.empty_note'),t('action.explore_equipment'),'catalog')}${cta()}</section>`)}
function updateSaved(path){if(!PAGES.some(p=>p.path===path))return;const removing=isSaved(path);saved=removing?saved.filter(x=>x!==path):[...saved,path];try{localStorage.setItem('coolex-shortlist',JSON.stringify(saved))}catch{toast(t('shortlist.storage'))}if(currentPath()==='/shortlist'){render();$('#main')?.focus({preventScroll:true});return}$$('[data-save]').filter(x=>x.dataset.save===path).forEach(x=>{const on=isSaved(path),p=PAGES.find(p=>p.path===path);x.setAttribute('aria-pressed',String(on));if(x.classList.contains('save-card')){x.innerHTML=icon(on?'check':'bookmark');x.setAttribute('aria-label',t(on?'shortlist.remove_label':'shortlist.save_label',{title:pageTitle(p)}))}else x.innerHTML=icon(on?'check':'bookmark')+`<span>${escape(t(on?'shortlist.saved':'shortlist.save'))}</span>`});$$('[data-saved-count]').forEach(x=>x.textContent=saved.length);const a=$('.header-actions>a.icon-btn');if(a)a.setAttribute('aria-label',saved.length?t('shortlist.header_count',{count:saved.length}):t('nav.shortlist'));toast(t(removing?'shortlist.removed':'shortlist.added'),!removing)}
function openDialog(d){lastFocus=document.activeElement;d.showModal()}
function closeDialog(d){d.close();if(d.id==='media-dialog')d.innerHTML='';if(lastFocus?.isConnected)lastFocus.focus()}
function openSearch(){const d=$('#search-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="search-title">${escape(t('search.title'))}</h2><button class="icon-btn" data-close="search-dialog" aria-label="${escape(t('search.close'))}">${icon('close')}</button></div><div class="search-body"><form id="global-search-form"><div class="field-search">${icon('search')}<label class="sr-only" for="global-search">${escape(t('search.all_label'))}</label><input id="global-search" type="search" placeholder="${escape(t('search.global_placeholder'))}" autocomplete="off"></div></form><div class="search-suggestions" id="search-results"></div><div class="search-bottom"><span>${escape(t('search.note'))}</span><button class="btn btn-dark btn-small" data-action="all-search">${escape(t('search.all_results'))} ${icon('arrow')}</button></div></div>`;openDialog(d);searchResults('');$('#global-search').focus()}
function searchResults(q){let list=[...EQUIPMENT,...CONCEPTS].filter(p=>matches(I18n.searchText(p),q));if(!q)list=['/fryers','/soft-icecream-machines','/pizzaovens','/milkboilers-coffeebrewer-teabrewer'].map(x=>EQUIPMENT.find(p=>p.path===x));$('#search-results').innerHTML=`<p class="search-label">${escape(q?t('search.matches',{count:list.length}):t('search.popular'))}</p>`+(list.length?list.slice(0,7).map(p=>`<a href="${siteUrl(p.path)}" class="search-result"><img src="${escape(p.thumbnail)}" alt="" width="55" height="45"><span><strong>${escape(pageTitle(p))}</strong><small>${escape(groupTitle(p.group))}</small></span>${icon('arrow')}</a>`).join(''):`<p class="muted" style="font-size:.85rem;padding:20px 0">${escape(t('search.no_matches'))}</p>`)}
function openMenu(){
 const d=$('#menu-dialog');const alreadyOpen=d.open;
 languageRoot.remove();
 d.innerHTML=`<div class="dialog-head"><h2 id="menu-title">${escape(t('nav.explore'))}</h2><button class="icon-btn" data-close="menu-dialog" aria-label="${escape(t('nav.close'))}">${icon('close')}</button></div><div class="menu-language-section"><p class="menu-language-label">${escape(t('language.choose'))}</p><div id="menu-language-slot" class="menu-language-slot"></div></div><nav class="mobile-links" aria-label="${escape(t('nav.mobile'))}"><a href="/Coolex/">${escape(t('nav.home'))}</a><a href="/Coolex/catalog">${escape(t('footer.catalogue'))}</a><a href="/Coolex/videos">${escape(t('nav.watch'))}</a><a href="/Coolex/business-ideas">${escape(t('nav.ideas'))}</a><a href="/Coolex/contact-details">${escape(t('nav.showrooms'))}</a><a href="/Coolex/shortlist">${escape(t('nav.shortlist'))} (${saved.length})</a>${button(t('action.talk'),'btn-red',tel,'phone')}</nav>`;
 renderLanguageControl();
 if(alreadyOpen)lastFocus=$('.mobile-toggle');else openDialog(d);
}
mobileNavigation.addEventListener('change',()=>{
 if(!DATA)return;
 const menu=$('#menu-dialog');
 if(!mobileNavigation.matches&&menu.open){menu.close();$('.header-search')?.focus({preventScroll:true})}
 renderLanguageControl();
});
function openGallery(key,i){gallery=key==='home-art'?homeArtwork():key==='home-all'?[...HOME.photos,...HOME.catalogues,...HOME.navigationArtwork]:currentPage?.[key]||currentPage?.photos||[];galleryIndex=Number(i)||0;zoom=1;const d=$('#media-dialog');drawGallery();openDialog(d)}
function drawGallery(){const im=gallery[galleryIndex];if(!im)return;const title=currentPage?pageTitle(currentPage):t('media.coolex_collection');const d=$('#media-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="media-title">${escape(title)} · ${galleryIndex+1} / ${gallery.length}</h2><button class="icon-btn" data-close="media-dialog" aria-label="${escape(t('media.close_viewer'))}">${icon('close')}</button></div><div class="viewer-area" id="viewer-area"><img src="${escape(im.src)}" alt="${escape(t('media.image_alt',{title,index:galleryIndex+1}))}"></div><div class="viewer-controls"><span class="counter">${escape(t('media.viewer_help',{index:galleryIndex+1,count:gallery.length}))}</span><button class="icon-btn" data-action="previous-image" aria-label="${escape(t('media.previous_image'))}" ${galleryIndex===0?'disabled':''}>${icon('left')}</button><button class="icon-btn" data-action="next-image" aria-label="${escape(t('media.next_image'))}" ${galleryIndex===gallery.length-1?'disabled':''}>${icon('chevron')}</button><button class="icon-btn" data-action="zoom-out" aria-label="${escape(t('media.zoom_out'))}" ${zoom===1?'disabled':''}>${icon('minus')}</button><button class="btn btn-outline" data-action="zoom-fit">${escape(t('media.fit'))}</button><button class="icon-btn" data-action="zoom-in" aria-label="${escape(t('media.zoom_in'))}">${icon('plus')}</button><a class="btn btn-dark" href="${escape(im.src)}" download>${icon('download')}${escape(t('media.original'))}</a></div>`;applyZoom()}
function applyZoom(){const a=$('#viewer-area');if(!a)return;a.classList.toggle('zoomed',zoom>1);a.style.setProperty('--zoom-width',zoom*100+'%');$('[data-action="zoom-out"]').disabled=zoom===1;$('[data-action="zoom-in"]').disabled=zoom>=4;$('[data-action="zoom-fit"]').textContent=zoom===1?t('media.fit'):Math.round(zoom*100)+'%'}
function stepImage(n){const next=galleryIndex+n;if(next<0||next>=gallery.length)return;galleryIndex=next;zoom=1;const focused=document.activeElement?.dataset.action;drawGallery();const nextFocus=focused?$(`[data-action="${focused}"]`):null;(nextFocus&&!nextFocus.disabled?nextFocus:$('[data-close="media-dialog"]')).focus();announce(t('media.image_count',{index:galleryIndex+1,count:gallery.length}))}
function openVideo(key){const v=PAGES.flatMap(p=>p.videos).find(v=>v.key===key);if(!v)return;const d=$('#media-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="media-title">${escape(videoTitle(v))}</h2><button class="icon-btn" data-close="media-dialog" aria-label="${escape(t('media.close_video'))}">${icon('close')}</button></div><div class="video-stage">${v.type==='local'?`<video controls preload="metadata" playsinline poster="${escape(v.poster)}"><source src="${escape(v.src)}" type="video/mp4">${escape(t('media.unsupported'))}</video>`:`<iframe src="${escape(v.src)}" title="${escape(videoTitle(v))}" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`}</div><div class="provider-note"><span>${v.type==='youtube'?t('media.youtube_note'):t('media.local_note')}</span><a href="${escape(v.original)}" target="_blank" rel="noopener noreferrer">${v.type==='youtube'?t('media.open_youtube'):t('media.open_original')} ${icon('diagonal')}</a></div>`;openDialog(d)}
function selectTab(id,focus=false){const p=currentPage;if(!p)return;$$('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===id));b.tabIndex=b.dataset.tab===id?0:-1});$('#detail-panel').setAttribute('aria-labelledby','tab-'+id);$('#detail-panel').innerHTML=mediaPanel(p,id);const q=new URLSearchParams(location.search);q.set('view',id);history.replaceState(null,'',location.pathname+'?'+q);if(focus)$('#tab-'+id).focus()}
function render(){$('#announcer').textContent='';const path=currentPath();currentPage=PAGES.find(p=>p.path===path);let html;if(path==='/')html=homePage();else if(path==='/catalog'||path==='/search')html=directoryPage();else if(path==='/videos')html=videosPage();else if(path==='/business-ideas')html=ideasPage();else if(path==='/shortlist')html=shortlistPage();else if(path==='/heritage')html=heritagePage();else if(currentPage?.kind==='contact')html=contactPage();else if(currentPage)html=detailPage(currentPage);else html=frame(`<section class="wrap error-page"><p class="eyebrow">${escape(t('error.eyebrow'))}</p><h1>${escape(t('error.page'))}</h1><p>${escape(t('error.note'))}</p>${button(t('action.browse_equipment'))}</section>`);languageRoot.remove();$('#app').innerHTML=html;const key={'/catalog':'footer.catalogue','/search':'footer.catalogue','/videos':'nav.watch','/business-ideas':'nav.ideas','/shortlist':'nav.shortlist','/heritage':'heritage.title'}[path];document.title=(path==='/'?t('meta.home'):key?t(key):currentPage?pageTitle(currentPage):t('meta.explore'))+' | Coolex';document.documentElement.lang=I18n.locale;const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=path==='/heritage'?t('heritage.description'):currentPage?I18n.description(currentPage):t(path==='/videos'?'library.description':path==='/business-ideas'?'ideas.description':path==='/shortlist'?'shortlist.description':'catalogue.description');$('.skip').textContent=t('access.skip');renderLanguageControl();if($('#directory-search'))updateDirectory();if($('#featured-grid'))applyHomeGroup(homeGroup,false);layoutHeritageFrames()}
function route(url){const u=new URL(siteUrl(url),location.href);if(u.origin!==location.origin){location.href=url;return}$$('dialog[open]').forEach(d=>d.close());history.pushState(null,'',u.pathname+u.search+u.hash);selectedSheet=0;homeGroup='All';libraryLimit=24;render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true})}
document.addEventListener('click',async e=>{
 const chapter=e.target.closest('[data-heritage-page]');if(chapter){selectHeritagePage(chapter.dataset.heritagePage);return}
 const historySize=e.target.closest('[data-heritage-size]');if(historySize){setHeritageSize(historySize.dataset.heritageSize);return}
 const language=e.target.closest('[data-locale]');if(language){chooseLanguage(language.dataset.locale);return}
 const close=e.target.closest('[data-close]');if(close){closeDialog(document.getElementById(close.dataset.close));return}
 const save=e.target.closest('[data-save]');if(save){updateSaved(save.dataset.save);return}
 const video=e.target.closest('[data-video]');if(video){openVideo(video.dataset.video);return}
 const photo=e.target.closest('[data-gallery]');if(photo){openGallery(photo.dataset.gallery,photo.dataset.index);return}
 const sheet=e.target.closest('[data-sheet]');if(sheet&&!sheet.disabled){const i=Number(sheet.dataset.sheet);if(i>=0&&i<currentPage.catalogues.length){selectedSheet=i;const label=sheet.getAttribute('aria-label');const wasControl=sheet.classList.contains('icon-btn');$('#sheet-stage').innerHTML=sheetStage(currentPage,i);if(wasControl){const next=$('#sheet-stage [aria-label="'+label+'"]');(next&&!next.disabled?next:$('#sheet-stage .icon-btn:not(:disabled)')||$('#sheet-stage .btn')).focus()}$$('[data-sheet].sheet-thumb').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.sheet)===i)));announce(t('media.sheet_label',{index:i+1}))}return}
 const tab=e.target.closest('[data-tab]');if(tab){selectTab(tab.dataset.tab);return}
 const group=e.target.closest('[data-group]');if(group){setFilters({group:group.dataset.group});return}
 const hg=e.target.closest('[data-home-group]');if(hg){applyHomeGroup(hg.dataset.homeGroup);return}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action){if(action==='search')openSearch();if(action==='menu')openMenu();if(action==='catalog')route('/catalog');if(action==='reset-filters')setFilters({q:'',group:'All',sort:'featured'});if(action==='clear-directory'){setFilters({q:''});$('#directory-search').focus()}if(action==='all-search')route('/catalog?q='+encodeURIComponent($('#global-search').value));if(action==='more-videos'){libraryLimit+=24;updateDirectory()}if(action==='previous-image')stepImage(-1);if(action==='next-image')stepImage(1);if(action==='zoom-in'){zoom=Math.min(4,zoom+.5);applyZoom()}if(action==='zoom-out'){zoom=Math.max(1,zoom-.5);applyZoom()}if(action==='zoom-fit'){zoom=1;applyZoom()}if(action==='copy-shortlist'){const text=t('shortlist.copy_title')+'\n'+PAGES.filter(p=>isSaved(p.path)).map(p=>'• '+pageTitle(p)).join('\n')+'\n'+t('shortlist.copy_contact')+' '+phone;try{await navigator.clipboard.writeText(text);toast(t('shortlist.copied'))}catch{const d=$('#search-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="search-title">${escape(t('shortlist.copy_dialog'))}</h2><button class="icon-btn" data-close="search-dialog" aria-label="${escape(t('action.close'))}">${icon('close')}</button></div><div class="search-body"><textarea style="width:100%;min-height:200px" readonly>${escape(text)}</textarea></div>`;openDialog(d);$('textarea',d).select()}}return}
 const a=e.target.closest('a[href]');if(a&&a.origin===location.origin&&a.pathname.startsWith(SITE_BASE)&&!a.hasAttribute('download')&&a.target!=='_blank'&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){if(a.getAttribute('href').startsWith('#'))return;if(a.pathname.startsWith('/Coolex/assets/'))return;e.preventDefault();route(a.href)}
});
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='directory-search')setFilters({q:e.target.value})});
document.addEventListener('change',e=>{if(e.target.id==='sort-order')setFilters({sort:e.target.value})});
document.addEventListener('submit',e=>{if(e.target.id==='global-search-form'){e.preventDefault();const q=$('#global-search').value;const matchesNow=[...EQUIPMENT,...CONCEPTS].filter(p=>matches(I18n.searchText(p),q));if(matchesNow.length===1)route(matchesNow[0].path);else route('/catalog?q='+encodeURIComponent(q))}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-locale]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const languages=Object.keys(I18n.languages);const i=languages.indexOf(I18n.locale);const next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;chooseLanguage(languages[next]);return}const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);if(e.key==='/'&&!editing&&!$('dialog[open]')){e.preventDefault();openSearch()}if(e.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]');const i=tabs.indexOf(e.target);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[n].dataset.tab,true)}if($('#media-dialog').open&&$('#viewer-area')&&!editing){if(e.key==='ArrowLeft'){e.preventDefault();stepImage(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepImage(1)}if(e.key==='+'||e.key==='='){e.preventDefault();zoom=Math.min(4,zoom+.5);applyZoom()}if(e.key==='-'){e.preventDefault();zoom=Math.max(1,zoom-.5);applyZoom()}}});
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(d.id==='media-dialog')d.innerHTML=''});d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d)});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)})});
window.addEventListener('popstate',()=>{if(DATA){$$('dialog[open]').forEach(d=>d.close());render()}});
window.addEventListener('storage',e=>{if(e.key==='coolex-language'&&e.newValue)chooseLanguage(e.newValue,false);if(e.key==='coolex-shortlist'){try{saved=JSON.parse(e.newValue||'[]');if(!Array.isArray(saved))saved=[];render()}catch{}}});
Promise.all([I18n.ready,fetch('/Coolex/data.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()})]).then(([,data])=>{DATA=data;PAGES=data.pages;EQUIPMENT=PAGES.filter(p=>p.kind==='equipment');CONCEPTS=PAGES.filter(p=>p.kind==='concept');HOME=PAGES.find(p=>p.kind==='home');saved=saved.filter(x=>PAGES.some(p=>p.path===x));const seen=new Set();for(const p of PAGES){for(const v of p.videos){v.key=p.path+'::'+v.id;v.category=p.kind==='home'?'Coolex showroom':p.title;v.page=p.path;v.group=p.kind==='home'?'Showrooms':p.group;if(!seen.has(v.id)){seen.add(v.id);VIDEO_LIBRARY.push(v)}}}render()}).catch(err=>{$('#app').innerHTML=`<main class="wrap error-page"><h1>We couldn’t load the catalogue.</h1><p>${escape(t('error.reload',{phone}))}</p>${button('Call Coolex','btn-red',tel,'phone')}</main>`;console.error(err)});
})();
